const { exec } = require('child_process');

function startElectronApp() {
  return new Promise((resolve, reject) => {
    const pathtoWindow = "node_modules/neuralgraph/window.js";
    const electronProcess = exec(`electron ${pathtoWindow}`);

    electronProcess.stdout.on('data', (data) => {
      console.log(data);
    });

    electronProcess.stderr.on('data', (data) => {
      console.error(data);
    });

    electronProcess.on('close', (code) => {
      //console.log(`App exited with code ${code}`);
      resolve();
    });

    electronProcess.on('error', (err) => {
      console.error('Failed to start app:', err);
      reject(err);
    });
  });
}

async function GenerateGraph(model = null) {
  if (model) {
    try {
      await model.save('file://./model');
      Data.model = model;
      await startElectronApp();
    } catch (err) {
      console.error("Error saving model for 3D use: ", err);
    }
  }
}

module.exports = {
  startElectronApp,
  GenerateGraph
};

